    // Aperto de mão — Heroicons não tem; usar briefcase como Parceiros (já mapeado)
    'handshake':         'M20.25 14.15v4.25c0 1.094-.787 2.036-1.872 2.18-2.087.277-4.216.42-6.378.42s-4.291-.143-6.378-.42c-1.085-.144-1.872-1.086-1.872-2.18v-4.25m16.5 0a2.18 2.18 0 00.75-1.661V8.706c0-1.081-.768-2.015-1.837-2.175a48.114 48.114 0 00-3.413-.387m4.5 8.006c-.194.165-.42.295-.673.38A23.978 23.978 0 0112 15.75c-2.648 0-5.195-.429-7.577-1.22a2.016 2.016 0 01-.673-.38m0 0A2.18 2.18 0 013 12.489V8.706c0-1.081.768-2.015 1.837-2.175a48.111 48.111 0 013.413-.387m7.5 0V5.25A2.25 2.25 0 0013.5 3h-3a2.25 2.25 0 00-2.25 2.25v.894m7.5 0a48.667 48.667 0 00-7.5 0M12 12.75h.008v.008H12v-.008z',
};

// O path pode ter 2 segmentos (ex. map-pin) — separa em múltiplos <path>.
const segments = computed(() => {
    const p = PATHS[props.name];
    if (! p) {
        // fallback: "?" visual — evita crash mas torna ausência visível
        return ['M9.879 7.519c1.171-1.025 3.071-1.025 4.242 0 1.172 1.025 1.172 2.687 0 3.712-.203.179-.43.326-.67.442-.745.361-1.45.999-1.45 1.827v.5M12 18h.01'];
    }
    // separa por " M " para permitir paths compostos (evita bounding incorreto)
    return p.split(/\sM\s/).map((s, i) => (i === 0 ? s : 'M ' + s));
});
